package genesismesh

import (
	"encoding/json"
	"os"
	"testing"
	"time"
)

// Shared conformance suite "vouching" (1.8.0), generated by the Python
// reference (genesismesh/conformance/generate_vectors.py vouching) and copied
// unchanged: records of a succeeded NA key (attestations, treaties,
// revocation feeds and grants) judged at their own time and judged now. Every
// vector runs.

type vouchingVector struct {
	ID          string `json:"id"`
	Kind        string `json:"kind"`
	Model       string `json:"model"`
	Description string `json:"description"`
	Input       struct {
		Genesis       json.RawMessage `json:"genesis"`
		Successions   json.RawMessage `json:"successions"`
		RootPublicKey string          `json:"root_public_key"`
		Record        json.RawMessage `json:"record"`
		Now           string          `json:"now"`
		GraceSeconds  *float64        `json:"grace_seconds"`
	} `json:"input"`
	Expected struct {
		AtRecordTime *string `json:"at_record_time"`
		Now          *string `json:"now"`
	} `json:"expected"`
}

const vouchingSuiteFile = "testdata/conformance/vouching.json"

func loadVouchingVectors(t *testing.T) []vouchingVector {
	t.Helper()
	raw, err := os.ReadFile(vouchingSuiteFile)
	if err != nil {
		t.Fatal(err)
	}
	var suite struct {
		Suite   string           `json:"suite"`
		Vectors []vouchingVector `json:"vectors"`
	}
	if err := json.Unmarshal(raw, &suite); err != nil {
		t.Fatal(err)
	}
	if suite.Suite != "vouching" || len(suite.Vectors) < 32 {
		t.Fatalf("unexpected suite %q with %d vectors", suite.Suite, len(suite.Vectors))
	}
	return suite.Vectors
}

func vouchingHistory(t *testing.T, v vouchingVector) *NAKeyHistory {
	t.Helper()
	result, err := VerifyKeyHistory(v.Input.Genesis, v.Input.Successions, v.Input.RootPublicKey)
	if err != nil || !result.Verified {
		t.Fatalf("key history: %v %+v", err, result)
	}
	if v.Input.GraceSeconds != nil {
		return result.History.WithVouchingGrace(time.Duration(*v.Input.GraceSeconds * float64(time.Second)))
	}
	return result.History
}

func reasonOf(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func TestConformanceVouchingVectors(t *testing.T) {
	receipt := newReceipt(t, "vouching", vouchingSuiteFile)
	for _, v := range loadVouchingVectors(t) {
		v := v
		if v.Kind != "record_vouching" {
			t.Fatalf("%s: unknown kind %q", v.ID, v.Kind)
		}
		receipt.ran(v.Kind)
		t.Run(v.ID, func(t *testing.T) {
			h := vouchingHistory(t, v)
			now, err := ParseTimestamp(v.Input.Now)
			if err != nil {
				t.Fatal(err)
			}
			atRecord, err := NARecordRefusal(v.Model, v.Input.Record, h, nil)
			if err != nil {
				t.Fatal(err)
			}
			judgedNow, err := NARecordRefusal(v.Model, v.Input.Record, h, &now)
			if err != nil {
				t.Fatal(err)
			}
			if atRecord != reasonOf(v.Expected.AtRecordTime) || judgedNow != reasonOf(v.Expected.Now) {
				t.Fatalf("%s: got (%q, %q), want (%q, %q)", v.Description, atRecord, judgedNow,
					reasonOf(v.Expected.AtRecordTime), reasonOf(v.Expected.Now))
			}
		})
	}
}

func vouchingVectorByID(t *testing.T, id string) vouchingVector {
	t.Helper()
	for _, v := range loadVouchingVectors(t) {
		if v.ID == id {
			return v
		}
	}
	t.Fatalf("no vector %s", id)
	return vouchingVector{}
}

func TestVouchingHorizonHelpers(t *testing.T) {
	succeeded := time.Date(2026, 1, 11, 0, 0, 0, 0, time.UTC)
	validTo := succeeded.Add(365 * 24 * time.Hour)
	h := &NAKeyHistory{Keys: []NAKey{
		{KeySequence: 1, PublicKey: "old", SucceededAt: &succeeded},
		{KeySequence: 2, PublicKey: "new", ValidFrom: &succeeded, ValidTo: &validTo, ValidToEnforced: true},
	}}
	if h.VouchingGrace() != SuccessionVouchingGrace {
		t.Fatalf("default grace %v", h.VouchingGrace())
	}
	short := h.WithVouchingGrace(time.Hour)
	horizon := succeeded.Add(SuccessionHandover + time.Hour)
	if got := short.VouchesUntil("old"); got == nil || !got.Equal(horizon) {
		t.Fatalf("vouches until %v, want %v", got, horizon)
	}
	if short.RecordOutlivesKey("old", horizon.Add(-time.Nanosecond)) || !short.RecordOutlivesKey("old", horizon) {
		t.Fatal("the horizon is exclusive of its last instant")
	}
	before := succeeded.Add(-time.Second)
	if got := short.KeysVouchingAt(before, horizon.Add(-time.Second)); len(got) != 1 || got[0] != "old" {
		t.Fatalf("keys vouching inside the grace: %v", got)
	}
	if got := short.KeysVouchingAt(before, horizon); len(got) != 0 {
		t.Fatalf("keys vouching past the horizon: %v", got)
	}
	// The new key ends at its enforced valid_to; a key with no end, or outside the history, has none.
	if got := short.VouchesUntil("new"); got == nil || !got.Equal(validTo.Add(SuccessionHandover+time.Hour)) {
		t.Fatalf("new key vouches until %v", got)
	}
	if NAKeysValidAlways([]string{"k"}).VouchesUntil("k") != nil || short.VouchesUntil("stranger") != nil {
		t.Fatal("a key with no end vouches without a horizon")
	}
	// The grace only shortens, and the original history is unchanged.
	if short.WithVouchingGrace(10*time.Hour).VouchingGrace() != time.Hour || h.VouchingGrace() != SuccessionVouchingGrace {
		t.Fatal("WithVouchingGrace lengthened the grace or changed the original")
	}
	if h.WithVouchingGrace(-time.Second).VouchingGrace() != 0 {
		t.Fatal("a negative grace is 0")
	}
}

func TestVouchingGraceHintInTheKeyHistoryResponse(t *testing.T) {
	v := vouchingVectorByID(t, "attestation-old-key-within-grace")
	grace := func(hint interface{}) time.Duration {
		body, _ := json.Marshal(map[string]interface{}{
			"genesis": json.RawMessage(v.Input.Genesis), "successions": json.RawMessage(v.Input.Successions),
			"vouching_grace_seconds": hint,
		})
		result, err := VerifyKeyHistoryResponse(body, v.Input.RootPublicKey)
		if err != nil || !result.Verified {
			t.Fatalf("%v %+v", err, result)
		}
		return result.History.VouchingGrace()
	}
	if grace(600) != 600*time.Second || grace(10*86400) != SuccessionVouchingGrace || grace("600") != SuccessionVouchingGrace ||
		grace(nil) != SuccessionVouchingGrace {
		t.Fatal("the hint must only shorten the grace")
	}
}

func TestVerifyCapabilityGrantAtAppliesTheHorizon(t *testing.T) {
	inside := vouchingVectorByID(t, "grant-old-key-within-grace")
	past := vouchingVectorByID(t, "grant-old-key-after-horizon")
	h := vouchingHistory(t, inside)
	insideNow, _ := ParseTimestamp(inside.Input.Now)
	pastNow, _ := ParseTimestamp(past.Input.Now)
	if r, err := VerifyCapabilityGrantAt(inside.Input.Record, h, insideNow); err != nil || r.Reason != "accepted" {
		t.Fatalf("inside the grace: %+v %v", r, err)
	}
	if r, err := VerifyCapabilityGrantAt(past.Input.Record, h, pastNow); err != nil || r.Reason != "outlives_key" || r.Valid {
		t.Fatalf("past the horizon: %+v %v", r, err)
	}
	if r, err := VerifyCapabilityGrant(past.Input.Record, h); err != nil || r.Reason != "accepted" {
		t.Fatalf("at its own time: %+v %v", r, err)
	}
	fresh := vouchingVectorByID(t, "grant-new-key")
	freshNow, _ := ParseTimestamp(fresh.Input.Now)
	if r, err := VerifyCapabilityGrantAt(fresh.Input.Record, h, freshNow); err != nil || r.Reason != "accepted" {
		t.Fatalf("new key: %+v %v", r, err)
	}
}
